{"path":"services.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--glass-bg:rgba(255,255,255,0.08);--glass-border:rgba(255,255,255,0.12);--accent:#7cc6a0;--muted:#cbd5d9;--text:#eff5f4;--glass-blur:10px}
    html,body{height:100%;margin:0;background:linear-gradient(160deg,#0f1724 0%,#042027 60%);color:var(--text);font-family:system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial}
    .app{min-height:100%;display:flex;flex-direction:column}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px}
    nav a{color:var(--muted);text-decoration:none;margin:0 10px;font-weight:600}
    nav a.active{color:var(--text)}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:48px;height:48px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#1fb6a1);box-shadow:0 6px 18px rgba(0,0,0,0.45);display:flex;align-items:center;justify-content:center;font-weight:700}
    main{flex:1;padding:24px}
    .hero{display:grid;grid-template-columns:1fr 380px;gap:22px;align-items:center}
    .glass{background:var(--glass-bg);backdrop-filter:blur(var(--glass-blur));border:1px solid var(--glass-border);padding:22px;border-radius:14px}
    h1{margin:0 0 8px 0;font-size:28px}
    p.lead{margin:0;color:var(--muted)}

    /* pattern SVG layer */
    .pattern-layer{position:absolute;inset:0;pointer-events:none;opacity:0.06}
    svg.pattern{width:100%;height:100%}

    /* Services list */
    .services-list{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin-top:16px}
    .service{padding:14px;border-radius:12px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);border:1px solid rgba(255,255,255,0.03)}
    .service h3{margin:0 0 6px 0;font-size:16px}
    .service p{margin:0;color:var(--muted);font-size:14px}

    /* Proof gallery */
    .proof{margin-top:18px}
    .testimonial{display:flex;gap:12px;align-items:flex-start}
    .avatar{width:56px;height:56px;border-radius:10px;background:linear-gradient(45deg,#ffd1a9,#ff9aa2);flex:0 0 56px;display:flex;align-items:center;justify-content:center;font-weight:700;color:#1a2b2b}
    .quote{font-style:italic;color:var(--muted)}
    .badges{display:flex;gap:8px;margin-top:10px}
    .badge{background:rgba(255,255,255,0.03);padding:6px 8px;border-radius:8px;font-size:12px;cursor:default;position:relative}
    .tooltip{position:absolute;bottom:calc(100% + 8px);left:50%;transform:translateX(-50%);background:#0b1114;color:var(--muted);padding:8px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);white-space:nowrap;font-size:12px;display:none}
    .badge:hover .tooltip{display:block}

    /* Pricing comparator */
    .comparator{margin-top:18px;background:linear-gradient(180deg,rgba(124,198,160,0.08),transparent);padding:14px;border-radius:12px}
    .toggle{display:inline-flex;background:rgba(255,255,255,0.03);padding:4px;border-radius:999px;border:1px solid rgba(255,255,255,0.04)}
    .toggle button{background:none;border:none;color:var(--muted);padding:8px 12px;border-radius:999px;cursor:pointer}
    .toggle button.active{background:var(--accent);color:#042925}
    .price{margin-top:12px;font-size:28px;font-weight:700}
    .note{font-size:13px;color:var(--muted)}

    /* CTA */
    .cta{display:flex;gap:12px;margin-top:18px}
    .btn{padding:10px 14px;border-radius:10px;border:1px solid rgba(255,255,255,0.06);background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);color:var(--text);text-decoration:none}
    .btn.primary{background:linear-gradient(90deg,var(--accent),#3bb29a);color:#042925;border:none}

    footer{padding:18px 28px;color:var(--muted);font-size:13px}

    /* small screens */
    @media (max-width:900px){
      .hero{grid-template-columns:1fr;}
      .services-list{grid-template-columns:1fr}
    }
  </style>
</head>
<body>
  <div class='pattern-layer' aria-hidden='true'>
    <svg class='pattern' xmlns='http://www.w3.org/2000/svg' preserveAspectRatio='none'>
      <defs>
        <pattern id='p' width='40' height='40' patternUnits='userSpaceOnUse'>
          <rect width='40' height='40' fill='none'/>
          <path d='M0 20h40 M20 0v40' stroke='%2308a88a' stroke-width='0.8' stroke-opacity='0.7'/>
          <circle cx='20' cy='20' r='2' fill='%2308a88a' fill-opacity='0.5'/>
        </pattern>
      </defs>
      <rect width='100%' height='100%' fill='url(#p)' />
    </svg>
  </div>
  <div class='app'>
    <header>
      <div class='brand'>
        <div class='logo'>HM</div>
        <div>
          <div style='font-weight:700'>{{BUSINESS_NAME}}</div>
          <div style='font-size:12px;color:var(--muted)'>Holistic care with clear, personalized steps</div>
        </div>
      </div>
      <nav>
        <a href='index.html'>Home</a>
        <a href='services.html' class='active'>Offerings</a>
        <a href='conditions.html'>Ailments</a>
        <a href='approach.html'>Method</a>
        <a href='pricing.html'>Rates</a>
        <a href='about.html'>The Studio</a>
        <a href='book.html'>Book</a>
        <a href='contact.html'>Connect</a>
      </nav>
    </header>

    <main>
      <section class='hero'>
        <div class='glass'>
          <h1>Practical integrative sessions & supportive add-ons</h1>
          <p class='lead'>We weave evidence-informed practices—nutrition, movement, lifestyle, and gentle therapeutic tools—into a plan that fits your rhythm. Each offering pairs clinical care with at-home supports and optional retail add-ons.</p>

          <div class='services-list' aria-hidden='false'>
            <div class='service'>
              <h3>Foundational Visit</h3>
              <p>Comprehensive intake, gentle mapping of priorities, and a focused 60–75 minute plan to begin small changes.</p>
            </div>
            <div class='service'>
              <h3>Rhythm Sessions</h3>
              <p>30–45 minute follow-ups to refine plans and integrate practical tools between visits.</p>
            </div>
            <div class='service'>
              <h3>Deep Reset</h3>
              <p>90-minute guided reset for layered concerns, with toolkit recommendations and an at-home support pack.</p>
            </div>
            <div class='service'>
              <h3>Retail Add-On Packs</h3>
              <p>Curated supplements, calming blends, and guided resource sets you can add to sessions as supportive aids.</p>
            </div>
          </div>

          <div class='comparator' aria-label='Pricing comparator'>
            <div style='display:flex;align-items:center;justify-content:space-between'>
              <div>
                <strong>Compare payment options</strong>
                <div class='note'>Toggle between monthly support and a single-package price.</div>
              </div>
              <div class='toggle' role='tablist' aria-label='pricing toggle'>
                <button class='toggle-btn active' data-mode='monthly' role='tab' aria-selected='true'>Monthly</button>
                <button class='toggle-btn' data-mode='package' role='tab' aria-selected='false'>Package</button>
              </div>
            </div>
            <div class='price' id='priceDisplay'>$<span id='priceNumber'>120</span><span style='font-weight:400;font-size:14px;color:var(--muted)'> /mo</span></div>
            <div class='note'>Includes access to messaging support and priority scheduling for active clients.</div>
          </div>

          <div class='cta'>
            <a class='btn primary' href='{{PRIMARY_CTA_URL}}'>Explore a tailored path</a>
            <a class='btn' href='pricing.html'>See full rates</a>
          </div>
        </div>

        <aside class='glass' aria-labelledby='testHeading'>
          <h3 id='testHeading'>Voices from your community</h3>
          <div class='proof' id='proofGallery'>
            <div class='testimonial' id='testimonialBlock'>
              <div class='avatar' id='tAvatar'>A</div>
              <div>
                <div class='quote' id='tQuote'>"I learned small ways to feel steadier day to day — no dramatic overhaul, just clearer steps."</div>
                <div style='margin-top:8px;font-size:13px;color:var(--muted)'>— <span id='tAuthor'>A. Rivera</span></div>
                <div class='badges' id='tBadges'>
                  <div class='badge'>Local Clinic<div class='tooltip'>Community clinic collaboration since 2018</div></div>
                  <div class='badge'>Certified Herbalist<div class='tooltip'>Third-party certificate and peer-reviewed coursework</div></div>
                </div>
              </div>
            </div>
            <div style='margin-top:12px;font-size:13px;color:var(--muted)'>Credibility badges rotate with testimonials — hover a badge for context.</div>
          </div>
        </aside>
      </section>

      <section style='margin-top:18px' class='glass'>
        <h3>Benefits you'll notice</h3>
        <ul style='margin:8px 0 0 16px;color:var(--muted)'>
          <li>Actionable tools you can use between visits</li>
          <li>Plans that respect your schedule and resources</li>
          <li>Optional retail supports chosen with intention</li>
        </ul>
      </section>

      <section style='margin-top:18px' class='glass'>
        <h3>How a typical process unfolds</h3>
        <ol style='margin:8px 0 0 16px;color:var(--muted)'>
          <li>Intake & priorities — we listen and map a short plan.</li>
          <li>Practical steps — small, weekly targets plus checks.</li>
          <li>Adjust & support — fine-tune tools, supplements, and at-home practices.</li>
        </ol>
      </section>

      <section style='margin-top:18px' class='glass'>
        <h3>Common questions</h3>
        <details style='margin-top:8px;color:var(--muted)'><summary>Do you take insurance?</summary><div style='margin-top:8px'>We provide receipts you may submit to insurers where allowable, and we can discuss options during booking.</div></details>
        <details style='margin-top:8px;color:var(--muted)'><summary>Are supplements required?</summary><div style='margin-top:8px'>No. We propose evidence-informed suggestions; choosing products is optional and personalized.</div></details>
      </section>

    </main>

    <footer>
      <div style='display:flex;justify-content:space-between;align-items:center'>
        <div>{{CITY}}, {{STATE}} · <a href='tel:{{PHONE}}' style='color:var(--muted)'>{{PHONE}}</a> · <a href='mailto:{{EMAIL}}' style='color:var(--muted)'>{{EMAIL}}</a></div>
        <div style='font-size:13px;color:var(--muted)'>© <span id='year'></span> {{BUSINESS_NAME}}</div>
      </div>
    </footer>
  </div>

  <script>
    // year
    document.getElementById('year').textContent = new Date().getFullYear();

    // Proof gallery rotate
    (function(){
      const testimonials = [
        {quote:'I learned small ways to feel steadier day to day — clearer steps that fit my life.',author:'Alex R',avatar:'AR',badges:[{label:'Local Clinic',tip:'Regular collaboration with neighborhood clinics'},{label:'Community Workshops',tip:'Hosts practical workshops for local groups'}]},
        {quote:'The plan wasn\'t a prescription, it was a map I could follow — and revise with support.',author:'Sam J',avatar:'SJ',badges:[{label:'Clinical Supervision',tip:'Ongoing clinical supervision and peer review'},{label:'Patient-Led Tools',tip:'Resources co-developed with clients'}]},
        {quote:'Helpful product picks and simple movement suggestions made a real, gentle difference.',author:'Maya L',avatar:'ML',badges:[{label:'Herbal Sourcing',tip:'Ethical sourcing practices'},{label:'Evidence Informed',tip:'Recommendations grounded in current literature'}]}
      ];
      let i=0;const quoteEl=document.getElementById('tQuote');const authorEl=document.getElementById('tAuthor');const avatarEl=document.getElementById('tAvatar');const badgesEl=document.getElementById('tBadges');
      function render(){
        const t=testimonials[i];
        quoteEl.textContent='"'+t.quote+'"';
        authorEl.textContent=t.author;
        avatarEl.textContent=t.avatar;
        badgesEl.innerHTML='';
        t.badges.forEach(b=>{const bEl=document.createElement('div');bEl.className='badge';bEl.textContent=b.label;const tip=document.createElement('div');tip.className='tooltip';tip.textContent=b.tip;bEl.appendChild(tip);badgesEl.appendChild(bEl)});
      }
      render();
      setInterval(()=>{i=(i+1)%testimonials.length;render();},5000);
    })();

    // Pricing comparator animated numbers
    (function(){
      const monthlyBtn=document.querySelector(".toggle-btn[data-mode='monthly']");
      const packageBtn=document.querySelector(".toggle-btn[data-mode='package']");
      const priceTarget=document.getElementById('priceNumber');
      let current=120; let anim=null;
      const targets = {monthly:120, package:990};
      function animateTo(goal){
        if(anim) cancelAnimationFrame(anim);
        const start=current; const duration=500; const startTime=performance.now();
        function step(now){
          const t=Math.min(1,(now-startTime)/duration);
          const eased = t<0.5?2*t*t: -1 + (4-2*t)*t; // simple ease
          current = Math.round(start + (goal-start)*eased);
          priceTarget.textContent = current;
          if(t<1) anim=requestAnimationFrame(step);
        }
        anim=requestAnimationFrame(step);
      }
      document.querySelectorAll('.toggle-btn').forEach(btn=>btn.addEventListener('click',function(){
        document.querySelectorAll('.toggle-btn').forEach(b=>b.classList.remove('active'));
        this.classList.add('active');
        const mode=this.getAttribute('data-mode');
        if(mode==='monthly'){
          document.querySelector('#priceDisplay').innerHTML = "$<span id='priceNumber'>"+current+"</span><span style='font-weight:400;font-size:14px;color:var(--muted)'> /mo</span>";
          // rebind priceNumber
          priceTarget = document.getElementById('priceNumber');
        }
        else{
          document.querySelector('#priceDisplay').innerHTML = "$<span id='priceNumber'>"+current+"</span><span style='font-weight:400;font-size:14px;color:var(--muted)'> one-time</span>";
        }
        // update reference
        priceTarget = document.getElementById('priceNumber');
        animateTo(targets[mode]);
      }));

      // keep reference outside initial click
      window.addEventListener('DOMContentLoaded',()=>{
        // initial animation to render properly
        animateTo(120);
      });
    })();
  </script>
</body>
</html>"}
