<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Ailments & supportive care — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg1:#07151a;--glass:rgba(255,255,255,0.05);--muted:#b9c6c4;--accent:#8bd0b2;--text:#e8f5f1}
