  <script>
    // pricing comparator for approach page
    (function(){
      const btns=document.querySelectorAll('.cmp-btn');
      const numEl=document.getElementById('cmpNumber');
      let current=120; let anim=null;
      const targs={monthly:120,package:890};
      function animate(goal){
        if(anim) cancelAnimationFrame(anim);
        const start=current; const dur=450; const s=performance.now();
        function f(now){
          const p=Math.min(1,(now-s)/dur);
          const ease=p<0.5?2*p*p: -1 + (4-2*p)*p;
          current=Math.round(start + (goal-start)*ease);
          numEl.textContent=current;
          if(p<1) anim=requestAnimationFrame(f);
        }
        anim=requestAnimationFrame(f);
      }
      btns.forEach(b=>b.addEventListener('click',function(){
        btns.forEach(x=>x.classList.remove('active'));
        this.classList.add('active');
        const mode=this.getAttribute('data-mode');
        const wrap=document.getElementById('cmpPrice');
        if(mode==='monthly') wrap.innerHTML = "$<span id='cmpNumber'>"+current+"</span><span style='font-weight:400;font-size:13px;color:var(--muted)'> /mo</span>";
        else wrap.innerHTML = "$<span id='cmpNumber'>"+current+"</span><span style='font-weight:400;font-size:13px;color:var(--muted)'> one-time</span>";
        // rebind
        const newNum=document.getElementById('cmpNumber');
        // make sure reference points to new node
        Object.defineProperty(window,'numEl',{get:()=>newNum});
        animate(targs[mode]);
      }));

      // initial animation
      animate(120);
    })();
  </script>
